SELECT (SELECT COUNT(*)=10 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='usuarios_tributarios' AND column_name IN ('id','usuario','nombre','correo','clave_hash','cambiar_clave','clave_version','creado_por','created_at','updated_at')) AND (SELECT COUNT(*)=1 FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='usuarios_tributarios' AND index_name='usuario_tributario_login' AND non_unique=0);
